"use strict";(self.webpackChunk=self.webpackChunk||[]).push([["5915"],{12552(e,t,i){i.r(t),i.d(t,{metadata:()=>n,default:()=>c,frontMatter:()=>s,contentTitle:()=>l,toc:()=>h,assets:()=>r});var n=JSON.parse('{"id":"ManipulateOSMDatas","title":"Manipulate OSM Datas","description":"[//]: # (startConcept|useosmdatas)","source":"@site/../docs/ManipulateOSMDatas.md","sourceDirName":".","slug":"/ManipulateOSMDatas","permalink":"/gama-platform.github.io/wiki/ManipulateOSMDatas","draft":false,"unlisted":false,"editUrl":"https://github.com/gama-platform/gama/wiki/ManipulateOSMDatas/_edit","tags":[],"version":"current","frontMatter":{"title":"Manipulate OSM Datas"},"sidebar":"main","previous":{"title":"Recipes","permalink":"/gama-platform.github.io/wiki/Recipes"},"next":{"title":"Cleaning a line network","permalink":"/gama-platform.github.io/wiki/CleaningGISData"}}'),a=i(74848),o=i(28453);let s={title:"Manipulate OSM Datas"},l,r={},h=[];function d(e){let t={a:"a",code:"code",img:"img",li:"li",ol:"ol",p:"p",pre:"pre",...(0,o.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsxs)(t.p,{children:["This section will be presented as a quick tutorial, showing how to proceed to manipulate OSM (Open street map) data, clean them and load them into GAMA. We will use the software ",(0,a.jsx)(t.a,{href:"http://www.qgis.org/en/site/",children:"QGIS"})," to change the attributes of the OSM file."]}),"\n",(0,a.jsxs)(t.p,{children:["GAMA can also read and import OpenStreetMap data natively and create agents from them, without any external tool: see ",(0,a.jsx)(t.a,{href:"https://github.com/gama-platform/gama/blob/main/gama.extension.osm/models/Data/OpenStreetMap%20Data/models/OSM%20File%20Import.gaml",children:"Data > OpenStreetMap Data > models > OSM File Import.gaml"}),", available with the OpenStreetMap plugin. The tutorial below goes the other way round: it prepares the data outside GAMA and exports them to shapefiles, which GAMA reads directly."]}),"\n",(0,a.jsxs)(t.p,{children:["From the website ",(0,a.jsx)(t.a,{href:"https://www.openstreetmap.org/",children:"openstreetmap.org"}),", we will choose a place (in this example, we will take a neighborhood in New York City). Directly from the website, you can export the chosen area in the osm format."]}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{alt:"The Export panel of openstreetmap.org, showing the bounding box of the neighbourhood of New York that will be downloaded and the Export button.",src:i(84655).A+"",width:"1916",height:"823"})}),"\n",(0,a.jsxs)(t.p,{children:["We have now to manipulate the attributes for the exported osm file.\nSeveral softwares can be used, but we will focus on ",(0,a.jsx)(t.a,{href:"http://www.qgis.org/en/site/",children:"QGIS"}),", which is totally free and provides a lot of possibilities in term of manipulation of data."]}),"\n",(0,a.jsx)(t.p,{children:"Once you have installed correctly QGIS, launch QGIS Desktop, and start to import the topology from the osm file."}),"\n",(0,a.jsx)(t.p,{children:'QGis 3, the version we are using to build this tutorial, needs us to install a plugin to process files downloaded from OSM website. There are several versions of plugins allowing to do that. However, the most stable and simple one to use is QuickOSM. Go to your extension manager, select "All extensions" on the top left corner, look for "QuickOSM" extension and install it.'}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{alt:"The Plugins dialog of QGIS with QuickOSM selected in the list and the Install Plugin button, the three elements marked following the steps of the text.",src:i(5290).A+"",width:"1919",height:"932"})}),"\n",(0,a.jsx)(t.p,{children:"You should now be able to use the extension QuickOSM. Open its menu by entering the vector menu on the top QGis panel, go to QuickOSM, then select :"}),"\n",(0,a.jsxs)(t.ol,{children:["\n",(0,a.jsx)(t.li,{children:"OSM file"}),"\n",(0,a.jsx)(t.li,{children:"Browse your xml file."}),"\n",(0,a.jsx)(t.li,{children:'Browse to select the folder that will welcome the processed file through QGis (select the "includes" folder of your current GAMA project for more efficiency).'}),"\n",(0,a.jsx)(t.li,{children:"Select the format you want for your processed file (in the example, ESRI shapefile will give a .shp, very well processed by GAMA afterwards)."}),"\n",(0,a.jsx)(t.li,{children:"Open your file."}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{alt:"The QuickOSM panel: the OSM File tab (1), the directory where the shapefiles will be written (2), the ESRI Shapefile format (3), the file prefix (4) and the Open button (5).",src:i(87966).A+"",width:"1915",height:"978"})}),"\n",(0,a.jsx)(t.p,{children:"You will go back naturally to the main QGis UI and you downloaded OSM layer will be visible."}),"\n",(0,a.jsx)(t.p,{children:"Before beginning the layer treatment process with QGis, note that it is easier to use a separate shapefile for each entity when the objective is to use GAMA afterwards. Importing one shapefile per spatial entity makes it simpler to create one species per entity than to decline a single species through different attributes. If you want to represent buildings and houses, it's recommended to have two separated files : one for buildings and one for houses."}),"\n",(0,a.jsx)(t.p,{children:'First, we want buildings to be isolated from the other polygons. We can use the field \'building\' to make an attribute selection to do that. By opening the attribute table of the file, we can check that this field exists and that every building has been attributed a "yes". If other information are given, replace the information by "yes" to facilitate the process of selection. Once it\'s done, go to the attribute selection menu on the top panel and type this in the dialogue box : "building" = \'yes\'. Click on "select features" once it\'s done and close the window.'}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{alt:"The OsmFile layer in editing mode, its buildings drawn in orange over the street network, with the Toggle Editing entry of the layer menu selected.",src:i(2575).A+"",width:"1917",height:"961"})}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{alt:"The attribute table of OsmFile, with the building column outlined on the right: it is the field used to isolate the buildings.",src:i(78520).A+"",width:"1918",height:"933"})}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{alt:"The Select by Expression dialog, with the expression for the buildings (1), the Select Features button (2) and Close (3); the status bar reports 1838 selected features.",src:i(46079).A+"",width:"1918",height:"933"})}),"\n",(0,a.jsx)(t.p,{children:'If typed correctly, QGis should understand that you want to select only polygons that are recognized as buildings. The buildings polygons should be highlighted in yellow now. Save the selected features as a new .shp file in your "includes" folder. We called ours "OSM_For_GAMA_Buildings". The new layer which just appeared should only comprise buildings of the area.'}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{alt:"The Export submenu of the layer, with Save Selected Features As highlighted, so that the selected buildings are written to their own shapefile.",src:i(67233).A+"",width:"1918",height:"967"})}),"\n",(0,a.jsx)(t.p,{children:"Then, we can create a new field for the new buildings layer to allow a better handling in GAMA platform do differentiate colors : first, enter you attribute table of the layer."}),"\n",(0,a.jsx)(t.p,{children:"Then, go to edit mode (the pen icon on the top left corner) and select field calculator."}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{alt:"The attribute table of the buildings layer with the editing tool (1) and the field calculator (2) marked.",src:i(34036).A+"",width:"1918",height:"935"})}),"\n",(0,a.jsx)(t.p,{children:"Stay on the left hand side, we will now set up the field's characteristics, you can copy what you see in the screenshot below. Pay attention to selecting \"string\" to the field type, otherwise you won't be able to get the proper format of attributes in the following steps of this tutorial."}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{alt:"The left part of the Field Calculator dialog: Create a new field, the name of the attribute, its type and its length.",src:i(52689).A+"",width:"1916",height:"935"})}),"\n",(0,a.jsx)(t.p,{children:'We want to create this attribute and associate to it variables that will be colors. We want to ask QGis to do that randomly on its own. Therefore, we have to provide the software a function. Go to the "function editor" tab, click on the "+" to add a new function file and write these lines down after having deleted the default help :'}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{children:"from qgis.core import *\nfrom qgis.gui import *\nimport random, string\n\n@qgsfunction(args='auto', group='Custom')\ndef myFun(value1, feature, parent):\n    return random.choice([\"blue\",\"red\"])\n"})}),"\n",(0,a.jsx)(t.p,{children:"Save and run the function using the proper button on the bottom right corner."}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{alt:"The Function Editor of the Field Calculator, with the five elements named in the text: the length of the field (1), the button that adds a function (2), the Function Editor tab (3), the body of the Python function (4) and Save and Load Functions (5).",src:i(47029).A+"",width:"1918",height:"932"})}),"\n",(0,a.jsxs)(t.p,{children:["Then go to the expression type and call your function by typing :\n",(0,a.jsx)(t.code,{children:"myFun('attrForGam')"}),'\nClick on "Ok" which will get you back to your attribute table : you can now check the layer\'s attributes to see if the new field \'attrForGam\' has been filled with random values "red" or "blue".']}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{alt:"The Expression tab of the Field Calculator, where the new field is filled by an expression (2) and the preview shows the value blue.",src:i(1937).A+"",width:"1919",height:"933"})}),"\n",(0,a.jsx)(t.p,{children:"When you download data from OSM website, some fields might be missing. For instance, the file we downloaded here doesn't include the buildings' height. To give realistic aspects to our model, we want here to call another function to make QGis create a \"Height\" field and associate automatically a height to buildings between 20 and 50 meters high. You can repeat the previous steps for the 'attrForGam' field to create a 'Height' field using the following code :"}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{children:"from qgis.core import *\nfrom qgis.gui import *\nimport random, string\n\n@qgsfunction(args='auto', group='Custom')\ndef myFunHeight(value1, feature, parent):\n    return random.randrange(20, 50, 1)\n"})}),"\n",(0,a.jsxs)(t.p,{children:["Call this function in the expression tab with ",(0,a.jsx)(t.code,{children:"myFunHeight('Height')"}),". Then check that the new field has been added and save the attribute changes."]}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{alt:"The attribute table after the modification: the two new columns attrForGam and Height are filled, and the annotation points at the save button.",src:i(84084).A+"",width:"1917",height:"930"})}),"\n",(0,a.jsx)(t.p,{children:'Our work on the buildings layer is done. You don\'t have to save it since QGis is automatically saving the modifications you do on your files (the one we previously called "OSM_For_GAMA_Buildings").\nThe file for buildings is now ready to be used in GAMA for modelling. We now have to take care our other polygons and lines we downloaded.'}),"\n",(0,a.jsx)(t.p,{children:"We now want to add the main natural elements to our model : parks. For this, we only have to select the few parks we have in the area thanks to the spatial selection tool provided by QGis.\nTo do that, you have to use the original polygons layer you downloaded to make a spatial selection of the parks.\nTo select several polygons using this tool, just press shift + left click on each polygons you are interested with. Before beginning the selection, locate where the parks are so that you are sure the polygons you select are the parks you want to represent."}),"\n",(0,a.jsxs)(t.ol,{children:["\n",(0,a.jsx)(t.li,{children:"Select the polygon layer."}),"\n",(0,a.jsx)(t.li,{children:'Select the tool "select features by area or single click" on the top panel.'}),"\n",(0,a.jsx)(t.li,{children:"Select the right polygons using left click and pressing maj to select several polygons."}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{alt:"The selected park polygons are shown in yellow on the map.",src:i(41359).A+"",width:"330",height:"310"})}),"\n",(0,a.jsx)(t.p,{children:'Then, save the selected polygons as a new shapefile which will only comprise parks areas. For this tutorial, we called the parks shapefile "OSM_For_GAMA_Parks".'}),"\n",(0,a.jsx)(t.p,{children:"Finally, we need roads for our possible agents to travel the city. The shapefile already exists from the OSM file we downloaded. It is possible to modify it using the edition mode after selecting the lines layer, and delete the roads we don't want."}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{alt:"The road layer in editing mode: the layer (1), Toggle Editing (2), the digitizing toolbar (3) and, on a selected road, the nodes that can be moved or deleted (4).",src:i(6916).A+"",width:"1917",height:"928"})}),"\n",(0,a.jsx)(t.p,{children:'Don\'t forget to save your layer as a .shp file in your "includes" folder of your current GAMA project. For this tutorial, we call the roads shapefile "OSM_For_GAMA_Roads".'}),"\n",(0,a.jsx)(t.p,{children:"These steps can be repeated as many times as needed, according to the level of detail required by the model. OSM provides a large number of land use types, which cannot all be covered here; the procedure is always the one described above."}),"\n",(0,a.jsx)(t.p,{children:'You can now import your three .shp files that should be in your "includes" folder of your current project.'}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{children:'model OSMtutorial\n\nglobal {\n    // Global variables related to the Management units\n\n	file shapeFile1 <- file("../includes/OSM_For_GAMA_Buildings.shp");\n    file shapeFile2 <- file("../includes/OSM_For_GAMA_Parks.shp");\n	file shapeFile3 <- file("../includes/OSM_For_GAMA_Roads.shp");\n\n    //definition of the environment size from the shapefile.\n    //Note that is possible to define it from several files by using: geometry shape <- envelope(envelope(file1) + envelope(file2) + ...);\n    geometry shape <- envelope(envelope(shapeFile1) + envelope(shapeFile2) + envelope(shapeFile3));\n\n    init {\n    //Creation of Buildings agents from the shapefile (and reading some of the shapefile attributes)\n    create Buildings from: shapeFile1\n        with: (elementId: int(read(\'full_id\')), elementHeight: int(read(\'Height\')), elementColor: string(read(\'attrForGam\'))) ;\n\n    create Parks from: shapeFile2;\n\n    create Roads from: shapeFile3 where (each != nil);\n    }\n}\n\nspecies Buildings{\n    int elementId;\n    int elementHeight;\n    string elementColor;\n\n    aspect basic{\n    draw shape color: (elementColor = "blue") ? #blue : ( (elementColor = "red") ? #red : #yellow) depth: elementHeight;\n    }\n}\n\nspecies Parks {\n\n	aspect basic {\n		draw shape color: #green;\n	}\n}\n\nspecies Roads {\n\n	aspect basic {\n		draw shape color: #grey width: 3#meter;\n	}\n}\n\nexperiment main mode: gui {\n    output {\n    display HowToUseOpenStreetMap renderer:3d {\n       species Buildings aspect: basic;\n       species Parks aspect: basic;\n       species Roads aspect: basic;\n    }\n    }\n}\n'})}),"\n",(0,a.jsx)(t.p,{children:'Here is the result, with a special colorization of the different elements regarding the value of the attribute "attrForGama", an elevation regarding the value of the attribute "height", and basic species creation for roads and parks.'}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{alt:"The result in GAMA: the buildings of the neighbourhood displayed in three dimensions and coloured by the attrForGam attribute, with the park in green and the streets in grey.",src:i(64298).A+"",width:"1915",height:"933"})})]})}function c(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},84655(e,t,i){i.d(t,{A:()=>n});let n=i.p+"assets/images/01_get_openstreetmap-33c6174a690eb807ad5d3d3cd5211f3a.png"},5290(e,t,i){i.d(t,{A:()=>n});let n=i.p+"assets/images/02_quickosm_plugin-2563bce98edacfb1c137bfd11dd9c86c.png"},87966(e,t,i){i.d(t,{A:()=>n});let n=i.p+"assets/images/03_import_and_open_osm_file-c144a88beb972bfeaaf87bcae75f5d30.png"},2575(e,t,i){i.d(t,{A:()=>n});let n=i.p+"assets/images/05_open_attributes-5a07f2a789e1cd8f2a1c8e4ca4184788.png"},78520(e,t,i){i.d(t,{A:()=>n});let n=i.p+"assets/images/06_check_existing_fields-75b17438be7d0e67cb41c9c92d59a18e.png"},46079(e,t,i){i.d(t,{A:()=>n});let n=i.p+"assets/images/07_select_buildings-4701d56c6b2cb4dfbb10110d89817adc.png"},67233(e,t,i){i.d(t,{A:()=>n});let n=i.p+"assets/images/08_save_selected_features-f371327eb00c7c7eb08731d3f8533542.png"},34036(e,t,i){i.d(t,{A:()=>n});let n=i.p+"assets/images/09_field_calculator-b4d7710db860546da4639f4de74df90d.png"},52689(e,t,i){i.d(t,{A:()=>n});let n=i.p+"assets/images/10_creating_attribute_1-abf6f8c44305b427db579ff154de1423.png"},47029(e,t,i){i.d(t,{A:()=>n});let n=i.p+"assets/images/11_creating_attribute_2-a01329fed7914dce1cf745fff353206d.png"},1937(e,t,i){i.d(t,{A:()=>n});let n=i.p+"assets/images/12_creating_attribute_3-4c6d1ede181d3c9d32b2c489b5aded18.png"},84084(e,t,i){i.d(t,{A:()=>n});let n=i.p+"assets/images/13_check_and_save_modifications-40fdb3d524f93d80963f9e1c64cfe2d9.png"},41359(e,t,i){i.d(t,{A:()=>n});let n=i.p+"assets/images/14_select_parks-177a26dee0a2bc670a4f9d89ae299c13.png"},6916(e,t,i){i.d(t,{A:()=>n});let n=i.p+"assets/images/15_modify_lines-75331233abb724c11c82906783ba2fd8.png"},64298(e,t,i){i.d(t,{A:()=>n});let n=i.p+"assets/images/16_final_gama-30c86c5faa96061fce8c62f243cf1e27.png"},28453(e,t,i){i.d(t,{R:()=>s,x:()=>l});var n=i(96540);let a={},o=n.createContext(a);function s(e){let t=n.useContext(o);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function l(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),n.createElement(o.Provider,{value:t},e.children)}}}]);